const API_BASE = "http://127.0.0.1:5000/api";

// Fetch available form schemas
export const getAvailableForms = async () => {
  const response = await fetch(`${API_BASE}/forms`);
  if (!response.ok) throw new Error("Failed to fetch forms");
  return await response.json();
};

// Send message to chatbot endpoint dynamically
export const sendMessage = async (sessionId, formName, messageText) => {
  const response = await fetch(`${API_BASE}/chat`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      session_id: sessionId,
      form_name: formName, // Dynamic form selection passed here
      message: messageText
    })
  });
  if (!response.ok) throw new Error("Failed to send message");
  return await response.json();
};
